-- FK 정의 (학생 테이블 생성 시)
CREATE TABLE 학생 (
  학번      VARCHAR2(10) PRIMARY KEY,
  이름      VARCHAR2(20),
  학과코드  VARCHAR2(4),
  CONSTRAINT FK_학생_학과 FOREIGN KEY (학과코드)
    REFERENCES 학과(학과코드) ON DELETE CASCADE
);

-- 부모 행 삭제
DELETE FROM 학과 WHERE 학과코드 = 'CS';

CREATE TABLE 주문 (
  주문번호 CHAR(10) PRIMARY KEY,
  고객번호 CHAR(5)  NULL
    REFERENCES 고객(고객번호)
);
CREATE TABLE 주문상세 (
  주문번호 CHAR(10)
    REFERENCES 주문(주문번호),
  순번     NUMBER(3),
  수량     NUMBER(5),
  PRIMARY KEY (주문번호, 순번)
);

